mapper.select:

WHERE 1=1


    AND p.product_id = #{productId}



    AND p.product_code like concat('%', #{productCode}, '%')



    AND p.product_name like concat('%', #{productName}, '%')



    AND p.product_type = #{productType}



    AND p.product_specifications like concat('%', #{productSpecifications}, '%')



    AND p.measure_unit like concat('%', #{measureUnit}, '%')



    AND p.product_barcode like concat('%', #{productBarcode}, '%')



    AND p.default_warehouse = #{defaultWarehouse}



    AND date_format(u.create_time,'%y%m%d') >= date_format(#{params.beginTime},'%y%m%d')



    AND date_format(u.create_time,'%y%m%d') <= date_format(#{params.endTime},'%y%m%d')



    AND p.status = #{status}

SELECT p.product_id, p.product_code, p.product_name, p.product_type, p.product_specifications, p.measure_unit, p.producer, p.cost_price, p.univalence, p.discount, pt.product_type_name, (
) AS inventory_qty, (
) AS lock_qty FROM product p JOIN product_type pt ON pt.product_type_id = p.product_type WHERE 1=1
AND p.product_id = #{productId}
AND p.product_code like concat('%', #{productCode}, '%')
AND p.product_name like concat('%', #{productName}, '%')

SELECT
(

) AS lock_qty
FROM product p
WHERE 1=1


    AND p.product_id = #{productId}
